3	Card	40	1	2026-08-20 18:47:17.992962+00	{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":23,"database_id":4,"collection_id":null,"query_type":"native","name":"Mean search latency by search mode","type":"question","cache_ttl":null,"dataset_query":{"stages":[{"lib/type":"mbql.stage/native","native":"WITH last_runs AS (\\n    SELECT run_id, started_at\\n    FROM evaluation.search_evaluation_runs\\n    WHERE status = 'completed'\\n    ORDER BY started_at DESC\\n    LIMIT 10\\n)\\nSELECT\\n    r.run_id,\\n    lr.started_at AS run_timestamp,\\n    r.mode AS search_mode,\\n    AVG(r.search_latency_ms) AS mean_search_latency_ms\\nFROM last_runs AS lr\\nJOIN evaluation.search_evaluation_results AS r\\n    USING (run_id)\\nGROUP BY r.run_id, lr.started_at, r.mode\\nORDER BY lr.started_at DESC, r.mode;"}],"lib/type":"mbql/query","database":4},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.dimensions":["run_timestamp","search_mode"],"graph.series_order_dimension":null,"graph.series_order":null,"series_settings":{"vector":{"color":"#227FD2"},"hybrid":{"color":"#E75454"},"text":{"color":"#88BF4D"}},"graph.x_axis.scale":"timeseries","graph.metrics":["mean_search_latency_ms"]},"parameters":[],"dashboard_id":2}	f	t	\N	f	v0.63.14 (8429d62)
